def header(lang, kind='', depth=1):
 c=COPY[lang]; up='../'*depth; other='en' if lang=='es' else 'es'; route=f'{kind}/' if kind else ''
 return f'''<a class="skip" href="#main">{c['skip']}</a><header class="header wrap"><a class="brand" href="{up}{lang}/" aria-label="Wing"><img src="{up}assets/wing-icon.jpg" width="44" height="44" alt=""><span class="wordmark">Wing</span></a><nav aria-label="{'Navegación principal' if lang=='es' else 'Main navigation'}"><a class="desktop-link" href="{up}{lang}/#discover">{c['features']}</a><a class="desktop-link" href="{up}{lang}/#plan">{c['plan']}</a><a href="mailto:info@legal-assistant-ai.com">{c['support']}</a><a class="language" href="{up}{other}/{route}" lang="{other}" aria-label="{'Read in English' if other=='en' else 'Leer en español'}">{'EN' if other=='en' else 'ES'}</a></nav></header>'''

def footer(lang, depth=1):
 c=COPY[lang]; up='../'*depth
 return f'''<footer class="footer wrap"><div class="footer-top"><a class="brand" href="{up}{lang}/"><img src="{up}assets/wing-icon.jpg" width="44" height="44" alt=""><span class="wordmark">Wing</span></a><nav class="footer-links" aria-label="{'Información legal' if lang=='es' else 'Legal information'}"><a href="{up}{lang}/privacy-policy/">{c['privacy']}</a><a href="{up}{lang}/terms-and-conditions/">{c['terms']}</a><a href="mailto:info@legal-assistant-ai.com">{c['support']}</a></nav></div><p class="copyright">© 2026 Wing. {c['rights']} · NIF B26788224</p></footer>'''

def page(lang,title,desc,body,route='',depth=1):
 up='../'*depth
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="theme-color" content="#103e35"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="{URL}/{lang}/{route}"><link rel="alternate" hreflang="es" href="{URL}/es/{route}"><link rel="alternate" hreflang="en" href="{URL}/en/{route}"><link rel="alternate" hreflang="x-default" href="{URL}/en/{route}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="{URL}/{lang}/{route}"><meta property="og:image" content="{URL}/assets/wing-icon.jpg"><meta property="og:image:alt" content="Wing"><link rel="icon" href="{up}assets/favicon.png"><link rel="stylesheet" href="{up}styles.css?v=2"></head><body>{body}</body></html>'''

def home(lang):
 c=COPY[lang]; strip=''.join(f'<span>{s}</span>' for s in c['strip'])
 cards=''.join(f'<article class="feature"><span class="number">0{i+1}</span><h3>{title}</h3><p>{desc}</p></article>' for i,(title,desc) in enumerate(c['cards']))
 steps=''.join(f'<li><span class="dot">{i+1}</span><div><strong>{title}</strong>{desc}</div></li>' for i,(title,desc) in enumerate(c['steps']))
 faq=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in c['faqs'])
 bullets=''.join(f'<li>{s}</li>' for s in c['list'])
 body=header(lang)+f'''<main id="main"><section class="hero wrap"><div><span class="eyebrow">{c['eyebrow']}</span><h1>{c['headline']}</h1><p class="intro">{c['intro']}</p><a class="button" href="#discover">{c['explore']} <span aria-hidden="true">↗</span></a><p class="micro">{c['soon']}</p></div><div class="hero-visual"><div class="orbit" aria-hidden="true"></div><div class="phone"><img src="../assets/discover.jpg" width="650" height="1407" alt="{c['screen']}" fetchpriority="high"></div><div class="floating-note"><span class="sound-icon" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span>{c['note']}</div></div></section><div class="wrap"><div class="feature-strip">{strip}</div></div>
<section class="section wrap" id="discover"><div class="section-intro"><span class="eyebrow">{c['sectioneye']}</span><h2>{c['sectiontitle']}</h2><p>{c['sectionbody']}</p></div><div class="features">{cards}</div></section>
<section class="wrap"><div class="showcase"><div><span class="eyebrow">{c['showeye']}</span><h2>{c['showtitle']}</h2><p>{c['showbody']}</p><ul class="mini-list">{bullets}</ul></div><div class="phone"><img src="../assets/identify.jpg" width="650" height="1407" alt="{'Captura real de Wing en inglés — identificación por sonido' if lang=='es' else 'Actual Wing screenshot in English — sound identification'}" loading="lazy"></div></div><div class="nature"><img src="../assets/hoopoe.jpg" width="1400" height="933" alt="{'Abubilla común en la hierba' if lang=='es' else 'Eurasian hoopoe in the grass'}" loading="lazy"><h2>{c['nature']}</h2><div class="photo-credit"><a href="https://commons.wikimedia.org/wiki/File:Israel._Eurasian_Hoopoe_(6497645007).jpg">{c['photo']}</a><br><a href="https://creativecommons.org/licenses/by/2.0/">CC BY 2.0</a></div></div></section>
<section class="section wrap price-section" id="plan"><div><span class="eyebrow">{c['priceeye']}</span><h2>{c['pricetitle']}</h2><p class="intro">{c['pricebody']}</p><p class="micro">{c['soon']}</p></div><div class="price-card"><span class="eyebrow">{c['annual']}</span><div class="price-line"><span class="price">{'39,99 €' if lang=='es' else '€39.99'}</span><span>{c['peryear']}</span></div><p>{c['trial']}</p><ol class="steps">{steps}</ol><p class="fine-print">{c['pricenote']}</p><p class="fine-print"><a href="terms-and-conditions/">{c['terms']}</a> · <a href="privacy-policy/">{c['privacy']}</a></p></div></section>
<section class="section wrap" style="padding-top:0"><div class="faq"><h2>{c['faqtitle']}</h2>{faq}</div></section></main>'''+footer(lang)
 return page(lang,c['title'],c['desc'],body)

def legal(lang,kind,sections):
 c=COPY[lang]; privacy=kind=='privacy-policy'; title=c['privacy'] if privacy else c['terms']; intro=c['privintro'] if privacy else c['termsintro']; summary=c['privsummary'] if privacy else c['termssummary']
 toc=''.join(f'<a href="#{id}">{escape(title)}</a>' for id,title,_ in sections)
 content=''.join(f'<section id="{id}"><h2>{escape(title)}</h2>{copy}</section>' for id,title,copy in sections)
 body=header(lang,kind,2)+f'<main id="main" class="wrap"><div class="legal-hero"><div class="wrap"><span class="eyebrow">Wing</span><h1>{title}</h1><p>{intro}</p><p class="legal-date">{c["updated"]}</p></div></div><div class="legal-layout"><nav class="toc" aria-label="{c["contents"]}"><h2>{c["contents"]}</h2>{toc}</nav><article class="legal-copy"><div class="legal-summary"><p>{summary}</p></div>{content}</article></div></main>'+footer(lang,2)
 return page(lang,title+' — Wing',intro,body,kind+'/',2)

for lang in COPY:
 out=ROOT/lang;out.mkdir(exist_ok=True);(out/'index.html').write_text(home(lang))
 for kind,sections in [('privacy-policy',PRIVACY[lang]),('terms-and-conditions',TERMS[lang])]:
  target=out/kind;target.mkdir(exist_ok=True);(target/'index.html').write_text(legal(lang,kind,sections))

(ROOT/'index.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Wing — Discover the birds around you. Descubre las aves que te rodean."><title>Wing — Bird Identifier</title><link rel="stylesheet" href="styles.css?v=2"><link rel="icon" href="assets/favicon.png"><link rel="alternate" hreflang="en" href="'''+URL+'''/en/"><link rel="alternate" hreflang="es" href="'''+URL+'''/es/"></head><body><main class="language-home"><a class="brand" href="en/"><img src="assets/wing-icon.jpg" width="52" height="52" alt=""><span class="wordmark">Wing</span></a><h1>A whole world in every song.</h1><p>Un mundo por descubrir en cada canto.</p><nav aria-label="Language / Idioma"><a class="button" href="es/" lang="es">Español ↗</a><a class="button" href="en/" lang="en">English ↗</a></nav></main></body></html>''')
(ROOT/'.nojekyll').touch()
(ROOT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {URL}/sitemap.xml\n')
routes=['']+[f'{lang}/{kind}' for lang in COPY for kind in ['', 'privacy-policy/', 'terms-and-conditions/']]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{URL}/{route}</loc></url>' for route in routes)+'</urlset>')
(ROOT/'404.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found — Wing</title><body style="background:#f5f3e8;color:#103e35;font-family:system-ui;padding:10vw"><h1>That bird has flown.</h1><p>Esta página no existe. / This page does not exist.</p><a href="'''+URL+'''/es/">Español</a> · <a href="'''+URL+'''/en/">English</a></body></html>''')
print('Generated 7 pages, sitemap, robots.txt and 404.html')
